 const checkbox = document.getElementById('termsCheckbox');
 const errorMessage = document.getElementById('termsError');

 form.addEventListener('submit', (e) => {
   e.preventDefault();

   if (!checkbox.checked) {
     // Show error message
     errorMessage.textContent = 'Error: You must agree to the terms to continue.';
     errorMessage.hidden = false;
     checkbox.setAttribute('aria-invalid', 'true');

     // Move focus to checkbox for accessibility
     checkbox.focus();
   } else {
     // Clear error if it was shown
     errorMessage.textContent = '';
     errorMessage.hidden = true;
     checkbox.setAttribute('aria-invalid', 'false');

     // Simulate form submission success
     alert('Thank you! You have successfully accepted the terms of use.');
     form.reset();
   }
 });

 // Clear error when user checks the box
 checkbox.addEventListener('change', () => {
   if (checkbox.checked) {
     errorMessage.textContent = '';
     errorMessage.hidden = true;
     checkbox.setAttribute('aria-invalid', 'false');
   }
 });

